diff --git a/include/net/strparser.h b/include/net/strparser.h
index 7dc131d62ad5..d96b59f45eba 100644
--- a/include/net/strparser.h
+++ b/include/net/strparser.h
@@ -74,10 +74,9 @@ struct strparser {
 	u32 unrecov_intr : 1;

 	struct sk_buff **skb_nextp;
-	struct timer_list msg_timer;
 	struct sk_buff *skb_head;
 	unsigned int need_bytes;
-	struct delayed_work delayed_work;
+	struct delayed_work msg_timer_work;
 	struct work_struct work;
 	struct strp_stats stats;
 	struct strp_callbacks cb;

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the use of a timer (`struct timer_list msg_timer`) in the message timeout handling, which could lead to taking a socket lock in a bottom half (BH) context. This is problematic because it can result in deadlocks or other concurrency issues, as the timer functions are executed in a non-preemptible context where certain locks should not be held.

        Commit message:
        strparser: Use delayed work instead of timer for msg timeout

Sock lock may be taken in the message timer function which is a
problem since timers run in BH. Instead of timers use delayed_work.

Reported-by: Eric Dumazet <eric.dumazet@gmail.com>
Fixes: bbb03029a899 ("strparser: Generalize strparser")
Signed-off-by: Tom Herbert <tom@quantonium.net>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:
         /* Lower lock held */
 static void strp_abort_strp(struct strparser *strp, int err)
 {
 	/* Unrecoverable error in receive */

-	del_timer(&strp->msg_timer);
+	cancel_delayed_work(&strp->msg_timer_work);

 	if (strp->stopped)
 		return;

 	strp->stopped = 1;

 	if (strp->sk) {
 		struct sock *sk = strp->sk;

 		/* Report an error on the lower socket */
 		sk->sk_err = err;
 		sk->sk_error_report(sk);
 	}
 }

 static void strp_start_timer(struct strparser *strp, long timeo)
 {
 	if (timeo)
-		mod_timer(&strp->msg_timer, timeo);
+		mod_delayed_work(strp_wq, &strp->msg_timer_work, timeo);
 }

 /* Lower socket lock held */
 static int __strp_recv(read_descriptor_t *desc, struct sk_buff *orig_skb,
 		       unsigned int orig_offset, size_t orig_len,
 		       size_t max_msg_size, long timeo)
 {
 	struct strparser *strp = (struct strparser *)desc->arg.data;
 	struct _strp_msg *stm;
 	struct sk_buff *head, *skb;
 	size_t eaten = 0, cand_len;
 	ssize_t extra;
 	int err;
 	bool cloned_orig = false;

 	if (strp->paused)
 		return 0;

 	head = strp->skb_head;
 	if (head) {
 		/* Message already in progress */

 		stm = _strp_msg(head);
 		if (unlikely(stm->early_eaten)) {
 			/* Already some number of bytes on the receive sock
 			 * data saved in skb_head, just indicate they
 			 * are consumed.
 			 */
 			eaten = orig_len <= stm->early_eaten ?
 				orig_len : stm->early_eaten;
 			stm->early_eaten -= eaten;

 			return eaten;
 		}

 		if (unlikely(orig_offset)) {
 			/* Getting data with a non-zero offset when a message is
 			 * in progress is not expected. If it does happen, we
 			 * need to clone and pull since we can't deal with
 			 * offsets in the skbs for a message expect in the head.
 			 */
 			orig_skb = skb_clone(orig_skb, GFP_ATOMIC);
 			if (!orig_skb) {
 				STRP_STATS_INCR(strp->stats.mem_fail);
 				desc->error = -ENOMEM;
 				return 0;
 			}
 			if (!pskb_pull(orig_skb, orig_offset)) {
 				STRP_STATS_INCR(strp->stats.mem_fail);
 				kfree_skb(orig_skb);
 				desc->error = -ENOMEM;
 				return 0;
 			}
 			cloned_orig = true;
 			orig_offset = 0;
 		}

 		if (!strp->skb_nextp) {
 			/* We are going to append to the frags_list of head.
 			 * Need to unshare the frag_list.
 			 */
 			err = skb_unclone(head, GFP_ATOMIC);
 			if (err) {
 				STRP_STATS_INCR(strp->stats.mem_fail);
 				desc->error = err;
 				return 0;
 			}

 			if (unlikely(skb_shinfo(head)->frag_list)) {
 				/* We can't append to an sk_buff that already
 				 * has a frag_list. We create a new head, point
 				 * the frag_list of that to the old head, and
 				 * then are able to use the old head->next for
 				 * appending to the message.
 				 */
 				if (WARN_ON(head->next)) {
 					desc->error = -EINVAL;
 					return 0;
 				}

 				skb = alloc_skb(0, GFP_ATOMIC);
 				if (!skb) {
 					STRP_STATS_INCR(strp->stats.mem_fail);
 					desc->error = -ENOMEM;
 					return 0;
 				}
 				skb->len = head->len;
 				skb->data_len = head->len;
 				skb->truesize = head->truesize;
 				*_strp_msg(skb) = *_strp_msg(head);
 				strp->skb_nextp = &head->next;
 				skb_shinfo(skb)->frag_list = head;
 				strp->skb_head = skb;
 				head = skb;
 			} else {
 				strp->skb_nextp =
 				    &skb_shinfo(head)->frag_list;
 			}
 		}
 	}

 	while (eaten < orig_len) {
 		/* Always clone since we will consume something */
 		skb = skb_clone(orig_skb, GFP_ATOMIC);
 		if (!skb) {
 			STRP_STATS_INCR(strp->stats.mem_fail);
 			desc->error = -ENOMEM;
 			break;
 		}

 		cand_len = orig_len - eaten;

 		head = strp->skb_head;
 		if (!head) {
 			head = skb;
 			strp->skb_head = head;
 			/* Will set skb_nextp on next packet if needed */
 			strp->skb_nextp = NULL;
 			stm = _strp_msg(head);
 			memset(stm, 0, sizeof(*stm));
 			stm->strp.offset = orig_offset + eaten;
 		} else {
 			/* Unclone since we may be appending to an skb that we
 			 * already share a frag_list with.
 			 */
 			err = skb_unclone(skb, GFP_ATOMIC);
 			if (err) {
 				STRP_STATS_INCR(strp->stats.mem_fail);
 				desc->error = err;
 				break;
 			}

 			stm = _strp_msg(head);
 			*strp->skb_nextp = skb;
 			strp->skb_nextp = &skb->next;
 			head->data_len += skb->len;
 			head->len += skb->len;
 			head->truesize += skb->truesize;
 		}

 		if (!stm->strp.full_len) {
 			ssize_t len;

 			len = (*strp->cb.parse_msg)(strp, head);

 			if (!len) {
 				/* Need more header to determine length */
 				if (!stm->accum_len) {
 					/* Start RX timer for new message */
 					strp_start_timer(strp, timeo);
 				}
 				stm->accum_len += cand_len;
 				eaten += cand_len;
 				STRP_STATS_INCR(strp->stats.need_more_hdr);
 				WARN_ON(eaten != orig_len);
 				break;
 			} else if (len < 0) {
 				if (len == -ESTRPIPE && stm->accum_len) {
 					len = -ENODATA;
 					strp->unrecov_intr = 1;
 				} else {
 					strp->interrupted = 1;
 				}
 				strp_parser_err(strp, len, desc);
 				break;
 			} else if (len > max_msg_size) {
 				/* Message length exceeds maximum allowed */
 				STRP_STATS_INCR(strp->stats.msg_too_big);
 				strp_parser_err(strp, -EMSGSIZE, desc);
 				break;
 			} else if (len <= (ssize_t)head->len -
 					  skb->len - stm->strp.offset) {
 				/* Length must be into new skb (and also
 				 * greater than zero)
 				 */
 				STRP_STATS_INCR(strp->stats.bad_hdr_len);
 				strp_parser_err(strp, -EPROTO, desc);
 				break;
 			}

 			stm->strp.full_len = len;
 		}

 		extra = (ssize_t)(stm->accum_len + cand_len) -
 			stm->strp.full_len;

 		if (extra < 0) {
 			/* Message not complete yet. */
 			if (stm->strp.full_len - stm->accum_len >
 			    strp_peek_len(strp)) {
 				/* Don't have the whole message in the socket
 				 * buffer. Set strp->need_bytes to wait for
 				 * the rest of the message. Also, set "early
 				 * eaten" since we've already buffered the skb
 				 * but don't consume yet per strp_read_sock.
 				 */

 				if (!stm->accum_len) {
 					/* Start RX timer for new message */
 					strp_start_timer(strp, timeo);
 				}

 				strp->need_bytes = stm->strp.full_len -
 						       stm->accum_len;
 				stm->accum_len += cand_len;
 				stm->early_eaten = cand_len;
 				STRP_STATS_ADD(strp->stats.bytes, cand_len);
 				desc->count = 0; /* Stop reading socket */
 				break;
 			}
 			stm->accum_len += cand_len;
 			eaten += cand_len;
 			WARN_ON(eaten != orig_len);
 			break;
 		}

 		/* Positive extra indicates ore bytes than needed for the
 		 * message
 		 */

 		WARN_ON(extra > cand_len);

 		eaten += (cand_len - extra);

 		/* Hurray, we have a new message! */
-		del_timer(&strp->msg_timer);
+		cancel_delayed_work(&strp->msg_timer_work);
 		strp->skb_head = NULL;
 		STRP_STATS_INCR(strp->stats.msgs);

 		/* Give skb to upper layer */
 		strp->cb.rcv_msg(strp, head);

 		if (unlikely(strp->paused)) {
 			/* Upper layer paused strp */
 			break;
 		}
 	}

 	if (cloned_orig)
 		kfree_skb(orig_skb);

 	STRP_STATS_ADD(strp->stats.bytes, eaten);

 	return eaten;
 }


-static void strp_msg_timeout(unsigned long arg)
+static void strp_msg_timeout(struct work_struct *w)
 {
-	struct strparser *strp = (struct strparser *)arg;
+	struct strparser *strp = container_of(w, struct strparser,
+					      msg_timer_work.work);

 	/* Message assembly timed out */
 	STRP_STATS_INCR(strp->stats.msg_timeouts);
 	strp->cb.lock(strp);
 	strp->cb.abort_parser(strp, ETIMEDOUT);
 	strp->cb.unlock(strp);
 }


 int strp_init(struct strparser *strp, struct sock *sk,
 	      const struct strp_callbacks *cb)
 {

 	if (!cb || !cb->rcv_msg || !cb->parse_msg)
 		return -EINVAL;

 	/* The sk (sock) arg determines the mode of the stream parser.
 	 *
 	 * If the sock is set then the strparser is in receive callback mode.
 	 * The upper layer calls strp_data_ready to kick receive processing
 	 * and strparser calls the read_sock function on the socket to
 	 * get packets.
 	 *
 	 * If the sock is not set then the strparser is in general mode.
 	 * The upper layer calls strp_process for each skb to be parsed.
 	 */

 	if (!sk) {
 		if (!cb->lock || !cb->unlock)
 			return -EINVAL;
 	}

 	memset(strp, 0, sizeof(*strp));

 	strp->sk = sk;

 	strp->cb.lock = cb->lock ? : strp_sock_lock;
 	strp->cb.unlock = cb->unlock ? : strp_sock_unlock;
 	strp->cb.rcv_msg = cb->rcv_msg;
 	strp->cb.parse_msg = cb->parse_msg;
 	strp->cb.read_sock_done = cb->read_sock_done ? : default_read_sock_done;
 	strp->cb.abort_parser = cb->abort_parser ? : strp_abort_strp;

-	setup_timer(&strp->msg_timer, strp_msg_timeout,
-		    (unsigned long)strp);
-
+	INIT_DELAYED_WORK(&strp->msg_timer_work, strp_msg_timeout);
 	INIT_WORK(&strp->work, strp_work);

